#include <vector>
using namespace std;

class Solution {
public:
    int computeAlternatingSum(vector<int>& nums) {
        int total = 0;
        int sign = 1;
        for (int x : nums) {
            total += sign * x;
            sign = -sign;
        }
        return total;
    }
};

class Solution {
    public int computeAlternatingSum(int[] nums) {
        int total = 0;
        int sign = 1;
        for (int x : nums) {
            total += sign * x;
            sign = -sign;
        }
        return total;
    }
}

var computeAlternatingSum = function(nums) {
    let total = 0;
    let sign = 1;
    for (const x of nums) {
        total += sign * x;
        sign = -sign;
    }
    return total;
};
